CREATE OR REPLACE FUNCTION public._assert_sanctions_screening(p_user_id uuid DEFAULT NULL::uuid)
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_uid       UUID := COALESCE(p_user_id, auth.uid());
  v_status    TEXT;
  v_screened  TIMESTAMPTZ;
